<script setup lang="ts">
import { ref, computed, watch, onMounted, onBeforeUnmount, nextTick } from 'vue';
import './styles/theme.css'; import './styles/listy.css';
const props = withDefaults(defineProps<{ items: unknown[]; itemKey?: (item: unknown, index: number) => string | number; height?: number; itemHeight?: number; dynamicHeight?: boolean; overscan?: number; endReachedThreshold?: number; emptyText?: string; footer?: string; split?: boolean }>(), { height: 320, itemHeight: 44, overscan: 4, endReachedThreshold: 120, emptyText: '暂无数据', split: true });
const emit = defineEmits<{ endReached: []; visibleRangeChange: [range: { start: number; end: number }] }>();
const viewport = ref<HTMLElement | null>(null); const top = ref(0); const heights = ref<Record<number, number>>({}); let endFired = false; let observer: ResizeObserver | undefined;
const offsets = computed(() => { const result = [0]; props.items.forEach((_, index) => { result[index + 1] = result[index] + (props.dynamicHeight ? heights.value[index] ?? props.itemHeight : props.itemHeight); }); return result; });
function find(value: number) { let low = 0, high = props.items.length - 1; while (low < high) { const mid = (low + high) >> 1; if (offsets.value[mid + 1] <= value) low = mid + 1; else high = mid; } return low; }
const start = computed(() => Math.max(0, find(top.value) - props.overscan)); const end = computed(() => Math.min(props.items.length, find(top.value + props.height) + 1 + props.overscan));
watch([start, end], ([start, end]) => emit('visibleRangeChange', { start, end }), { immediate: true });
watch(() => props.items, () => { heights.value = {}; endFired = false; }); watch(() => props.items.length, () => { endFired = false; });
function scroll() { const target = viewport.value; if (!target) return; top.value = target.scrollTop; if (!endFired && target.scrollTop + target.clientHeight >= target.scrollHeight - props.endReachedThreshold) { endFired = true; emit('endReached'); } }
async function observeRows() { await nextTick(); observer?.disconnect(); if (!props.dynamicHeight || !viewport.value) return; viewport.value.querySelectorAll<HTMLElement>('[data-index]').forEach(element => observer?.observe(element)); }
onMounted(() => { if (typeof ResizeObserver !== 'undefined') observer = new ResizeObserver(entries => { const next = { ...heights.value }; let changed = false; entries.forEach(entry => { const element = entry.target as HTMLElement; const index = Number(element.dataset.index); const height = element.getBoundingClientRect().height; if (Math.abs((next[index] ?? props.itemHeight) - height) >= 0.5) { next[index] = height; changed = true; } }); if (changed) heights.value = next; }); void observeRows(); }); watch([start, end, () => props.dynamicHeight], observeRows); onBeforeUnmount(() => observer?.disconnect());
function scrollTo(index: number, align: 'start' | 'center' | 'end' = 'start') { index = Math.max(0, Math.min(index, props.items.length - 1)); const position = offsets.value[index] ?? 0; const height = (offsets.value[index + 1] ?? position + props.itemHeight) - position; viewport.value?.scrollTo({ top: Math.max(0, align === 'center' ? position - (props.height - height) / 2 : align === 'end' ? position - props.height + height : position) }); }
defineExpose({ scrollTo, scrollToTop: () => viewport.value?.scrollTo({ top: 0 }) });
</script>
<template><div :class="['at-listy', { 'at-listy--split': split }]" :style="{ height: `${height}px` }"><div ref="viewport" class="at-listy__viewport" role="list" @scroll="scroll"><div v-if="!items.length" class="at-listy__empty"><slot name="empty">{{ emptyText }}</slot></div><div v-else class="at-listy__spacer" :style="{ height: `${offsets[items.length]}px` }"><div v-for="(item, offset) in items.slice(start, end)" :key="itemKey?.(item, start + offset) ?? start + offset" role="listitem" class="at-listy__item" :data-index="start + offset" :style="{ transform: `translateY(${offsets[start + offset]}px)`, height: dynamicHeight ? undefined : `${itemHeight}px` }"><slot :item="item" :index="start + offset">{{ item }}</slot></div></div><div v-if="footer || $slots.footer" class="at-listy__footer"><slot name="footer">{{ footer }}</slot></div></div></div></template>
